test('invoiceTotals calculates VAT correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 0 }],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 100 * 9500;
  const vat = Math.round((subtotal * 21) / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal + vat);
});

test('invoiceTotals calculates VAT after discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 100 * 9500;
  const discount = Math.round((subtotal * 10) / 100);
  const amountAfterDiscount = subtotal - discount;
  const vat = Math.round((amountAfterDiscount * 21) / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

test('invoiceTotals sums VAT from multiple lines with different rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const line1Total = 10 * 9500;
  const line2Total = 100 * 37;
  const subtotal = line1Total + line2Total;
  const vat1 = Math.round((line1Total * 21) / 100);
  const vat2 = Math.round((line2Total * 9) / 100);
  const totalVat = vat1 + vat2;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.vat, totalVat);
  assert.equal(totals.total, subtotal + totalVat);
});

test('invoiceTotals with zero VAT rate', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 }],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 60000;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, subtotal);
});

