test('renderInvoiceText VAT is shown before total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  const vatIndex = lines.findIndex((line) => line.startsWith('VAT:'));
  const totalIndex = lines.findIndex((line) => line.startsWith('Total:'));
  assert.ok(vatIndex >= 0);
  assert.ok(totalIndex > vatIndex);
});
